// Ingest Pipeline for Product Events
export const ProductEventPipeline = new IngestPipeline<ProductEvent>(
  "ProductEvent",
  {
    ingestApi: true,  // POST /ingest/ProductEvent
    stream: true,     // Redpanda topic "ProductEvent"
    table: {          // ClickHouse table with optimal ordering
      orderByFields: ["event_type", "product_id", "event_ts"]
    },
  }
);

// Materialized View 1: Top Products (view/cart/purchase counts and revenue)
interface TopProductsRow {
  product_id: string;
  view_count: number;
  cart_count: number;
  purchase_count: number;
  total_revenue: number;
}

export const topProductsMV = new MaterializedView<TopProductsRow>({
  tableName: "TopProducts",
  materializedViewName: "top_products_mv",
  orderByFields: ["product_id"],
  selectStatement: sql`
    SELECT
      product_id,
      countIf(event_type = 'view') AS view_count,
      countIf(event_type = 'cart') AS cart_count,
      countIf(event_type = 'purchase') AS purchase_count,
      sumIf(price, event_type = 'purchase') AS total_revenue
    FROM ProductEvent
    WHERE product_id IS NOT NULL
    GROUP BY product_id
  `,
  selectTables: [ProductEventPipeline.table!],
});

// Materialized View 2: Conversion Funnel (views → carts → purchases)
interface ConversionFunnelRow {
  user_id: string;
  product_id: string;
  has_view: number;
  has_cart: number;
  has_purchase: number;
  first_view_ts: Date;
  first_cart_ts: Date;
  first_purchase_ts: Date;
}

export const conversionFunnelMV = new MaterializedView<ConversionFunnelRow>({
  tableName: "ConversionFunnel",
  materializedViewName: "conversion_funnel_mv",
  orderByFields: ["user_id", "product_id"],
  selectStatement: sql`
    SELECT
      user_id,
      product_id,
      if(countIf(event_type = 'view') > 0, 1, 0) AS has_view,
      if(countIf(event_type = 'cart') > 0, 1, 0) AS has_cart,
      if(countIf(event_type = 'purchase') > 0, 1, 0) AS has_purchase,
      minIf(event_ts, event_type = 'view') AS first_view_ts,
      minIf(event_ts, event_type = 'cart') AS first_cart_ts,
      minIf(event_ts, event_type = 'purchase') AS first_purchase_ts
    FROM ProductEvent
    WHERE user_id IS NOT NULL AND product_id IS NOT NULL
    GROUP BY user_id, product_id
  `,
  selectTables: [ProductEventPipeline.table!],
});

// Materialized View 3: Hourly Activity (event counts per hour per type)
interface HourlyActivityRow {
  hour: Date;
  event_type: string;
  event_count: number;
  unique_users: number;
}

export const hourlyActivityMV = new MaterializedView<HourlyActivityRow>({
  tableName: "HourlyActivity",
  materializedViewName: "hourly_activity_mv",
  orderByFields: ["hour", "event_type"],
  selectStatement: sql`
    SELECT
      toStartOfHour(event_ts) AS hour,
      event_type,
      count() AS event_count,
      uniq(user_id) AS unique_users
    FROM ProductEvent
    WHERE event_ts IS NOT NULL AND event_type IS NOT NULL
    GROUP BY hour, event_type
  `,
  selectTables: [ProductEventPipeline.table!],
});

