  "ProductEvent",
  {
    ingestApi: true,  // POST /ingest/ProductEvent
    stream: true,     // Redpanda topic "ProductEvent"
    table: {          // ClickHouse table with optimal ordering
      orderByFields: ["event_type", "product_id", "event_ts"]
    },
