import { IngestPipeline, MaterializedView, Api, sql } from "@514labs/moose-lib";

// Product Event Data Model
export interface ProductEvent {
  event_id: string;
  event_ts: Date;
  user_id: string;
  product_id: string;
  event_type: string; // 'view', 'cart', 'purchase'
  price?: number; // only for purchase events
  properties: string; // JSON string for flexible properties
}

// Ingest Pipeline for Product Events
export const ProductEventPipeline = new IngestPipeline<ProductEvent>(
  "ProductEvent",
  {
    ingestApi: true,  // POST /ingest/ProductEvent
    stream: true,     // Redpanda topic "ProductEvent"
    table: {          // ClickHouse table with optimal ordering
      orderByFields: ["event_type", "product_id", "event_ts"]
    },
  }
);

// Materialized View 1: Top Products (view/cart/purchase counts and revenue)
interface TopProductsRow {
  product_id: string;
  view_count: number;
  cart_count: number;
  purchase_count: number;
  total_revenue: number;
}

export const topProductsMV = new MaterializedView<TopProductsRow>({
  tableName: "TopProducts",
  materializedViewName: "top_products_mv",
  orderByFields: ["product_id"],
  selectStatement: sql.statement`
    SELECT
      product_id,
      countIf(event_type = 'view') AS view_count,
      countIf(event_type = 'cart') AS cart_count,
      countIf(event_type = 'purchase') AS purchase_count,
      sumIf(price, event_type = 'purchase') AS total_revenue
    FROM ProductEvent
    WHERE product_id IS NOT NULL
    GROUP BY product_id
  `,
  selectTables: [ProductEventPipeline.table!],
});

// Materialized View 2: Conversion Funnel (views → carts → purchases)
interface ConversionFunnelRow {
  user_id: string;
  product_id: string;
  has_view: number;
  has_cart: number;
  has_purchase: number;
  first_view_ts: Date;
  first_cart_ts: Date;
  first_purchase_ts: Date;
}

export const conversionFunnelMV = new MaterializedView<ConversionFunnelRow>({
  tableName: "ConversionFunnel",
  materializedViewName: "conversion_funnel_mv",
  orderByFields: ["user_id", "product_id"],
  selectStatement: sql.statement`
    SELECT
      user_id,
      product_id,
      if(countIf(event_type = 'view') > 0, 1, 0) AS has_view,
      if(countIf(event_type = 'cart') > 0, 1, 0) AS has_cart,
      if(countIf(event_type = 'purchase') > 0, 1, 0) AS has_purchase,
      minIf(event_ts, event_type = 'view') AS first_view_ts,
      minIf(event_ts, event_type = 'cart') AS first_cart_ts,
      minIf(event_ts, event_type = 'purchase') AS first_purchase_ts
    FROM ProductEvent
    WHERE user_id IS NOT NULL AND product_id IS NOT NULL
    GROUP BY user_id, product_id
  `,
  selectTables: [ProductEventPipeline.table!],
});

// Materialized View 3: Hourly Activity (event counts per hour per type)
interface HourlyActivityRow {
  hour: Date;
  event_type: string;
  event_count: number;
  unique_users: number;
}

export const hourlyActivityMV = new MaterializedView<HourlyActivityRow>({
  tableName: "HourlyActivity",
  materializedViewName: "hourly_activity_mv",
  orderByFields: ["hour", "event_type"],
  selectStatement: sql.statement`
    SELECT
      toStartOfHour(event_ts) AS hour,
      event_type,
      count() AS event_count,
      uniq(user_id) AS unique_users
    FROM ProductEvent
    WHERE event_ts IS NOT NULL AND event_type IS NOT NULL
    GROUP BY hour, event_type
  `,
  selectTables: [ProductEventPipeline.table!],
});

// API 1: Top Products endpoint
interface TopProductsInput {
  limit?: number;
  sort_by?: 'view_count' | 'cart_count' | 'purchase_count' | 'total_revenue';
}

export const topProductsApi = new Api<TopProductsInput, TopProductsRow>(
  "top-products",
  async ({ limit = 10, sort_by = 'purchase_count' }, { client, sql }) => {
    const result = await client.query.execute(sql.statement`
      SELECT
        product_id,
        view_count,
        cart_count,
        purchase_count,
        total_revenue
      FROM TopProducts
      ORDER BY ${sql.fragment`${sort_by}`} DESC
      LIMIT ${limit}
    `);
    return await result.json();
  }
);

// API 2: Conversion Funnel endpoint
interface ConversionFunnelInput {
  user_id?: string;
  product_id?: string;
}

interface ConversionFunnelResponse {
  funnel_metrics: {
    total_users: number;
    users_with_views: number;
    users_with_carts: number;
    users_with_purchases: number;
    view_to_cart_rate: number;
    cart_to_purchase_rate: number;
    view_to_purchase_rate: number;
  };
  user_journeys?: ConversionFunnelRow[];
}

export const conversionFunnelApi = new Api<ConversionFunnelInput, ConversionFunnelResponse>(
  "conversion-funnel",
  async ({ user_id, product_id }, { client, sql }) => {
    // Build WHERE clause conditionally
    let whereClause = '';
    if (user_id || product_id) {
      const conditions = [];
      if (user_id) conditions.push(`user_id = '${user_id}'`);
      if (product_id) conditions.push(`product_id = '${product_id}'`);
      whereClause = 'WHERE ' + conditions.join(' AND ');
    }

    // Get overall funnel metrics
    const metricsResult = await client.query.execute(sql.statement`
      SELECT
        count() AS total_users,
        sumIf(has_view, has_view = 1) AS users_with_views,
        sumIf(has_cart, has_cart = 1) AS users_with_carts,
        sumIf(has_purchase, has_purchase = 1) AS users_with_purchases,
        round(users_with_carts / users_with_views * 100, 2) AS view_to_cart_rate,
        round(users_with_purchases / users_with_carts * 100, 2) AS cart_to_purchase_rate,
        round(users_with_purchases / users_with_views * 100, 2) AS view_to_purchase_rate
      FROM ConversionFunnel
      ${sql.fragment`${whereClause}`}
    `);

    const metrics = await metricsResult.json();

    // Get detailed user journeys if specific filters applied
    let userJourneys = null;
    if (user_id || product_id) {
      const journeyResult = await client.query.execute(sql.statement`
        SELECT * FROM ConversionFunnel
        ${sql.fragment`${whereClause}`}
        ORDER BY first_view_ts ASC
        LIMIT 100
      `);
      userJourneys = await journeyResult.json();
    }

    return {
      funnel_metrics: metrics[0],
      user_journeys: userJourneys
    };
  }
);

// API 3: Hourly Activity endpoint
interface HourlyActivityInput {
  hours?: number;
  event_type?: string;
}

export const hourlyActivityApi = new Api<HourlyActivityInput, HourlyActivityRow>(
  "hourly-activity",
  async ({ hours = 24, event_type }, { client, sql }) => {
    const eventTypeFilter = event_type ? `AND event_type = '${event_type}'` : '';

    const result = await client.query.execute(sql.statement`
      SELECT
        hour,
        event_type,
        event_count,
        unique_users
      FROM HourlyActivity
      WHERE hour >= subtractHours(now(), ${hours})
      ${sql.fragment`${eventTypeFilter}`}
      ORDER BY hour DESC, event_type ASC
    `);
    return await result.json();
  }
);

