// API 1: Top Products endpoint
interface TopProductsInput {
  limit?: number;
  sort_by?: string;
}

export const topProductsApi = new Api<TopProductsInput, TopProductsRow>(
  "top-products",
  async ({ limit = 10, sort_by = 'purchase_count' }, { client }) => {
    const validSortFields = ['view_count', 'cart_count', 'purchase_count', 'total_revenue'];
    const sortField = validSortFields.includes(sort_by) ? sort_by : 'purchase_count';

    const result = await client.query.execute(`
      SELECT
        product_id,
        view_count,
        cart_count,
        purchase_count,
        total_revenue
      FROM TopProducts
      ORDER BY ${sortField} DESC
      LIMIT ${limit}
    `);
    return await result.json();
  }
);

// API 2: Conversion Funnel endpoint
interface ConversionFunnelInput {
  user_id?: string;
  product_id?: string;
}

interface ConversionFunnelResponse {
  funnel_metrics: {
    total_users: number;
    users_with_views: number;
    users_with_carts: number;
    users_with_purchases: number;
    view_to_cart_rate: number;
    cart_to_purchase_rate: number;
    view_to_purchase_rate: number;
  };
  user_journeys?: ConversionFunnelRow[];
}

export const conversionFunnelApi = new Api<ConversionFunnelInput, ConversionFunnelResponse>(
  "conversion-funnel",
  async ({ user_id, product_id }, { client }) => {
    // Build WHERE clause
    let whereClause = '';
    const params = [];
    if (user_id || product_id) {
      const conditions = [];
      if (user_id) {
        conditions.push(`user_id = '${user_id}'`);
      }
      if (product_id) {
        conditions.push(`product_id = '${product_id}'`);
      }
      whereClause = 'WHERE ' + conditions.join(' AND ');
    }

    // Get overall funnel metrics
    const metricsQuery = `
      SELECT
        count() AS total_users,
        sum(has_view) AS users_with_views,
        sum(has_cart) AS users_with_carts,
        sum(has_purchase) AS users_with_purchases,
        round(sum(has_cart) / sum(has_view) * 100, 2) AS view_to_cart_rate,
        round(sum(has_purchase) / sum(has_cart) * 100, 2) AS cart_to_purchase_rate,
        round(sum(has_purchase) / sum(has_view) * 100, 2) AS view_to_purchase_rate
      FROM ConversionFunnel
      ${whereClause}
    `;

    const metricsResult = await client.query.execute(metricsQuery);
    const metrics = await metricsResult.json();

    // Get detailed user journeys if specific filters applied
    let userJourneys = null;
    if (user_id || product_id) {
      const journeyQuery = `
        SELECT * FROM ConversionFunnel
        ${whereClause}
        ORDER BY first_view_ts ASC
        LIMIT 100
      `;
      const journeyResult = await client.query.execute(journeyQuery);
      userJourneys = await journeyResult.json();
    }

    return {
      funnel_metrics: metrics[0],
      user_journeys: userJourneys
    };
  }
);

// API 3: Hourly Activity endpoint
interface HourlyActivityInput {
  hours?: number;
  event_type?: string;
}

export const hourlyActivityApi = new Api<HourlyActivityInput, HourlyActivityRow>(
  "hourly-activity",
  async ({ hours = 24, event_type }, { client }) => {
    let whereClause = `WHERE hour >= subtractHours(now(), ${hours})`;
    if (event_type) {
      whereClause += ` AND event_type = '${event_type}'`;
    }

    const query = `
      SELECT
        hour,
        event_type,
        event_count,
        unique_users
      FROM HourlyActivity
      ${whereClause}
      ORDER BY hour DESC, event_type ASC
    `;

    const result = await client.query.execute(query);
    return await result.json();
  }
);

